------------ import ------------
local KTool = CS.Engine.Lib.KTool
local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
------------ import ------------

---@class UIBattleSelectionMapNode

local UIBattleSelectionMapNode = Class('UIBattleSelectionMapNode')

function UIBattleSelectionMapNode:__init()
    self._systemId = 0
    self._serverData = nil
    self.actionHandler = Events.AddListener(Constants.EventNames.DAILY_SWEEP_QUEST_ACTION, Bind(self, self.SweepQuestEvent))
end

function UIBattleSelectionMapNode:__delete()
    self._systemId = 0
    self._serverData = nil
    if self.actionHandler then
        Events.RemoveListener(Constants.EventNames.DAILY_SWEEP_QUEST_ACTION, self.actionHandler)
        self.actionHandler = nil
    end
end

function UIBattleSelectionMapNode:Awake()
end

function UIBattleSelectionMapNode:SweepQuestEvent(data)
    if (not isNull(data)) and checkInt(data.systemId) == self._systemId then
        if type(self._serverData[tostring(self._systemId)]) == "string" or type(self._serverData[tostring(self._systemId)]) == "number" then
            self._serverData[tostring(self._systemId)] = data.times
        end
        self:FillSelf()
    end
end

function UIBattleSelectionMapNode:Refresh(systemId, data, isEntry)
    self._systemId = checkNumber(systemId)
    self._serverData = data
    if self._systemId <= 0 then
        return
    end
    self._isEntry = checkBool(isEntry)

    self:FillSelf()
end

function UIBattleSelectionMapNode:FillSelf()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(self._systemId)
    local aniName = ""
    if isUnlock then
        aniName = "" --"Open"
        --是入口
        if self._isEntry then
            aniName = "Open" --"Open"
        end
    else
        aniName = "Lock"
    end
    CfUtils.PlayAnimator(self.Anim, aniName)

    local status = isUnlock and 1 or 2
    CfUtils.SetUISwitchImage(self.PointState, status)
    CfUtils.SetUISwitchImage(self.TxtName, status)

    local isShowStar = false
    if checkNumber(self._systemId) == Constants.SystemToggleIds.Id4 or
            checkNumber(self._systemId) == Constants.SystemToggleIds.Id5 or
            checkNumber(self._systemId) == Constants.SystemToggleIds.Id6 then
        --日常
        --if self._serverData then
        isShowStar = true
        --end
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", self._systemId)
    if vo then
        CfUtils.FillText(self.TxtName, vo.name)
    end
    KTool.SetActive(self.TriangleGroup, isShowStar)
    if isShowStar then
        local type = 0
        if checkNumber(self._systemId) == Constants.SystemToggleIds.Id4 then
            type = 1
        elseif checkNumber(self._systemId) == Constants.SystemToggleIds.Id5 then
            type = 2
        elseif checkNumber(self._systemId) == Constants.SystemToggleIds.Id6 then
            type = 3
        end
        KTool.SetActive(self.TriangleGroup, true)
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting310, "DailyTypeVo", type)--日常副本类型表
        local allTime = checkNumber(vo.freeTimes)
        for i = 1, allTime do
            local go = self["ImgTriangle" .. i]
            if not isNull(go) then
                local status = 1
                if self._serverData then
                    status = (checkInt(self._serverData[checkString(self._systemId)]) >= i and 2 or 1)
                else
                    local dailyQuestDojo = dailyQuestComponent:GetDailyQuestDojoByType(type)
                    local freeTime = checkNumber(dailyQuestDojo.freeTimesRemain)
                    status = (freeTime >= i) and 2 or 1
                end
                if not go then return end
                if not status then return end
                local comp = go.transform:GetComponent(typeof(CS.Game.Native.Common.UISwitchImage))
                if not comp then
                    return
                end
                comp.Status = status
                comp:Reset()
                --CfUtils.SetUISwitchImage(go, status)
            end
        end
    end
end

function UIBattleSelectionMapNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBattleSelectionMapNode
